package android.content;import java.util.*;public class Context{public static final Context APP=new Context();public static final int RECEIVER_NOT_EXPORTED=4;public static final String POWER_SERVICE="power";public static final List<BroadcastReceiver> receivers=new ArrayList<>();public static boolean failRegistration;public final android.content.res.Resources resources=new android.content.res.Resources();public android.content.res.Resources getResources(){return resources;}public Context getApplicationContext(){return APP;}public Object getSystemService(String s){return new android.os.PowerManager();}public Intent registerReceiver(BroadcastReceiver r,IntentFilter f,int flags){receivers.add(r);if(failRegistration)throw new IllegalStateException("register after write");return null;}public void unregisterReceiver(BroadcastReceiver r){receivers.remove(r);}public static void broadcast(String a){for(var r:List.copyOf(receivers))r.onReceive(new Context(),new Intent(a));}}
